function diff(left,right,{json=false,keys=true,space=false}={}){if(left.length+right.length>400000)throw Error('Tổng nội dung tối đa 400.000 ký tự.');if(json){try{left=JSON.stringify(keys?canonical(JSON.parse(left)):JSON.parse(left),null,2)}catch{throw Error('JSON bên trái chưa hợp lệ.')}try{right=JSON.stringify(keys?canonical(JSON.parse(right)):JSON.parse(right),null,2)}catch{throw Error('JSON bên phải chưa hợp lệ.')}}const a=left===''?[]:left.replace(/\r\n?/g,'\n').split('\n'),b=right===''?[]:right.replace(/\r\n?/g,'\n').split('\n');if(a.length>2000||b.length>2000)throw Error('Mỗi bên tối đa 2.000 dòng. Hãy chia nhỏ nội dung.');const norm=s=>space?s.trim().replace(/\s+/g,' '):s,aa=a.map(norm),bb=b.map(norm),width=b.length+1,dp=new Uint16Array((a.length+1)*width);for(let i=a.length-1;i>=0;i--)for(let j=b.length-1;j>=0;j--)dp[i*width+j]=aa[i]===bb[j]?1+dp[(i+1)*width+j+1]:Math.max(dp[(i+1)*width+j],dp[i*width+j+1]);let i=0,j=0,added=0,removed=0;const rows=[];while(i<a.length||j<b.length){if(i<a.length&&j<b.length&&aa[i]===bb[j]){rows.push({kind:'same',old:i+1,new:j+1,text:b[j]});i++;j++}else if(j<b.length&&(i===a.length||dp[i*width+j+1]>dp[(i+1)*width+j])){rows.push({kind:'add',new:j+1,text:b[j++]});added++}else{rows.push({kind:'remove',old:i+1,text:a[i++]});removed++}}return {rows,added,removed,equal:added===0&&removed===0,text:rows.map(r=>(r.kind==='add'?'+ ':r.kind==='remove'?'- ':'  ')+r.text).join('\n')}}
function parseCSV(text,delimiter=','){if(![',',';','\t'].includes(delimiter))throw Error('Chọn dấu phân cách hợp lệ.');if(text.length>2000000)throw Error('CSV tối đa 2 MB ký tự.');text=text.replace(/^\uFEFF/,'');const rows=[];let row=[],cell='',quoted=false,closed=false,touched=false;const finishCell=()=>{row.push(cell);cell='';closed=false};const finishRow=()=>{finishCell();if(touched||row.length>1)rows.push(row);row=[];touched=false};for(let i=0;i<text.length;i++){const ch=text[i];if(quoted){if(ch==='"'){if(text[i+1]==='"'){cell+='"';i++}else{quoted=false;closed=true}}else cell+=ch;touched=true;continue}if(ch==='"'){if(cell||closed)throw Error('Dấu nháy CSV sai vị trí gần ký tự '+(i+1)+'.');quoted=true;touched=true}else if(ch===delimiter){finishCell();touched=true}else if(ch==='\r'||ch==='\n'){if(ch==='\r'&&text[i+1]==='\n')i++;finishRow()}else{if(closed)throw Error('Có ký tự sau dấu nháy đóng CSV.');cell+=ch;touched=true}}if(quoted)throw Error('CSV thiếu dấu nháy đóng.');if(touched||row.length||cell)finishRow();return rows}
