function jsonToCSV(text,delimiter=',',protect=false){text=text.replace(/^\uFEFF/,'');if(text.length>2000000)throw Error('JSON tối đa 2 MB ký tự.');if(![',',';','\t'].includes(delimiter))throw Error('Dấu phân cách chưa hợp lệ.');let rows;try{rows=JSON.parse(text)}catch{throw Error('JSON chưa hợp lệ.')}if(!Array.isArray(rows)||!rows.length||rows.some(r=>!r||typeof r!=='object'||Array.isArray(r)))throw Error('JSON phải là mảng không rỗng chứa các đối tượng.');if(rows.length>20000)throw Error('Tối đa 20.000 bản ghi.');const headers=[...new Set(rows.flatMap(Object.keys))];if(!headers.length)throw Error('Không có trường để xuất CSV.');if(headers.length>200)throw Error('Tối đa 200 cột.');const quote=value=>{let v=value==null?'':typeof value==='object'?JSON.stringify(value):String(value);if(protect&&typeof value==='string'&&/^[\s]*[=+@-]/.test(v))v="'"+v;return /["\r\n]/.test(v)||v.includes(delimiter)?'"'+v.replace(/"/g,'""')+'"':v};return {text:[headers.map(quote).join(delimiter),...rows.map(r=>headers.map(h=>quote(Object.hasOwn(r,h)?r[h]:null)).join(delimiter))].join('\r\n'),count:rows.length,columns:headers.length,extension:'csv'}}
function regex(pattern,flags,text){if(pattern.length>5000||text.length>100000)throw Error('Biểu thức tối đa 5.000 ký tự, nội dung tối đa 100.000 ký tự.');if(/[^dgimsuy]/.test(flags)||new Set(flags).size!==flags.length)throw Error('Flags chỉ gồm d g i m s u y và không lặp.');let re;try{re=new RegExp(pattern,flags)}catch(e){throw Error('Biểu thức chưa hợp lệ: '+e.message)}const matches=[];let m,budget=0,truncated=false;while((m=re.exec(text))!==null){const trim=s=>s==null?null:String(s).slice(0,2000);const item={index:m.index,length:m[0].length,text:trim(m[0]),groups:m.slice(1,51).map(trim),indices:m.indices?m.indices.slice(0,51):undefined,named:m.groups?Object.fromEntries(Object.entries(m.groups).slice(0,50).map(([k,v])=>[k,trim(v)])):null};budget+=JSON.stringify(item).length;if(matches.length>=500||budget>1000000){truncated=true;break}matches.push(item);if(!re.global&&!re.sticky)break;if(m[0]===''){const n=re.lastIndex;re.lastIndex=n+((re.unicode&&text.codePointAt(n)>0xffff)?2:1)}}return {matches,truncated,text:JSON.stringify(matches,null,2)}}
function qrPayload(data){const clean=s=>String(s||'').replace(/[\r\n]/g,' '),wifi=s=>String(s||'').replace(/[\\;,:"\r\n]/g,c=>'\\'+c);if(data.type==='wifi'){if(!data.ssid?.trim())throw Error('Nhập tên mạng Wi-Fi.');const auth=['WPA','WEP','nopass'].includes(data.auth)?data.auth:'WPA';if(auth!=='nopass'&&!data.password)throw Error('Nhập mật khẩu Wi-Fi hoặc chọn mạng mở.');return `WIFI:T:${auth};S:${wifi(data.ssid)};P:${auth==='nopass'?'':wifi(data.password)};H:${data.hidden?'true':'false'};;`}if(data.type==='contact'){if(!data.name?.trim())throw Error('Nhập tên liên hệ.');const v=s=>clean(s).replace(/[\\;,]/g,c=>'\\'+c);const parts=['BEGIN:VCARD','VERSION:3.0','FN:'+v(data.name)];for(const [key,label] of [['company','ORG'],['phone','TEL'],['email','EMAIL'],['website','URL']])if(data[key]?.trim())parts.push(label+':'+v(data[key]));parts.push('END:VCARD');return parts.join('\r\n')}if(data.type==='url'){let u;try{u=new URL(data.text)}catch{throw Error('Nhập URL đầy đủ bắt đầu bằng https:// hoặc http://.')}if(!['https:','http:'].includes(u.protocol))throw Error('URL cần dùng HTTP hoặc HTTPS.');return u.href}if(!data.text?.trim())throw Error('Nhập nội dung cần tạo QR.');return data.text}
